from typing import List

def filter_by_prefix(strings: List[str], prefix: str, case_sensitive: bool = True) -> List[str]:
    """
    Filter an input list of strings to include only those that start with a given prefix.

    Args:
    - strings (List[str]): The list of strings to filter.
    - prefix (str): The prefix to match.
    - case_sensitive (bool): Whether the comparison should be case-sensitive. Defaults to True.

    Returns:
    - List[str]: A new list containing only the strings that start with the specified prefix.
    """
    # Define a comparison function based on case sensitivity
    def matches_prefix(s: str) -> bool:
        if case_sensitive:
            return s.startswith(prefix)
        else:
            return s.lower().startswith(prefix.lower())

    # Filter the list using the comparison function
    return [s for s in strings if matches_prefix(s)]

