from typing import List
import math

def is_prime(num: int) -> bool:
    """Check if a number is prime."""
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def prime_fib(n: int) -> int:
    """
    prime_fib returns n-th number that is a Fibonacci number and it's also prime.

    :param n: The index of the prime Fibonacci number to find (1-indexed)
    :return: The n-th prime Fibonacci number
    """
    if not isinstance(n, int) or n <= 0:
        raise ValueError("Input must be a positive integer")

    a, b = 1, 1  # Starting Fibonacci numbers
    prime_fib_count = 0

    while prime_fib_count < n:
        # Check if current Fibonacci number is prime
        if is_prime(b):
            prime_fib_count += 1
            if prime_fib_count == n:
                return b

        # Generate next Fibonacci number
        a, b = b, a + b

