from typing import List

def monotonic(l: List[float]) -> bool:
    """
    Return True if list elements are monotonically increasing or decreasing.

    :param l: List of numbers to check for monotonicity
    :return: True if the list is monotonically increasing or decreasing, False otherwise
    """
    if len(l) <= 1:
        # By definition, empty lists and single-element lists are considered monotonic
        return True

    # Determine the trend based on the first two distinct elements
    is_increasing = None
    for i in range(1, len(l)):
        if l[i] > l[i - 1]:
            is_increasing = True
            break
        elif l[i] < l[i - 1]:
            is_increasing = False
            break

    if is_increasing is None:
        # All elements are equal, thus the list is both monotonically increasing and decreasing
        return True

    # Check the rest of the list for consistency with the determined trend
    for i in range(1, len(l)):
        if is_increasing and l[i] < l[i - 1]:
            return False
        elif not is_increasing and l[i] > l[i - 1]:
            return False

    return True

