from typing import List
import math

def is_prime(n: int) -> bool:
    """Check if a number is prime."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def get_primes_up_to(limit: int) -> List[int]:
    """Get a list of prime numbers up to the given limit."""
    return [i for i in range(2, limit + 1) if is_prime(i)]

def is_multiply_prime(a: int) -> bool:
    """Check if the given number is the product of exactly 3 prime numbers."""
    if a < 100:
        primes = get_primes_up_to(a)
        for i in range(len(primes)):
            for j in range(i, len(primes)):
                for k in range(j, len(primes)):
                    if primes[i] * primes[j] * primes[k] == a:
                        return True
    return False

# Example usage:
