from typing import List

def is_nested(string: str) -> bool:
    '''
    Check if there exists a valid subsequence of brackets in the input string
    that contains at least one nested bracket.

    Args:
    string (str): A string containing only square brackets.

    Returns:
    bool: True if a valid nested subsequence is found, False otherwise.
    '''

    def is_valid_subsequence(subseq: str) -> bool:
        '''Helper function to check if a subsequence is valid (balanced).'''
        balance = 0
        for bracket in subseq:
            if bracket == '[':
                balance += 1
            elif bracket == ']':
                balance -= 1
                if balance < 0:
                    return False
        return balance == 0

    def has_nesting(subseq: str) -> bool:
        '''Helper function to check if a valid subsequence has at least one nesting.'''
        depth = 0
        for bracket in subseq:
            if bracket == '[':
                depth += 1
                if depth > 1:  # If depth is more than 1, there's nesting
                    return True
            elif bracket == ']':
                depth -= 1
        return False

    # Generate all possible subsequences efficiently using bit manipulation
    n = len(string)
    for i in range(1, 2**n):  # 2**n possible subsequences (excluding empty)
        subseq = ''.join(string[j] for j in range(n) if (i & (1 << j)))
        if is_valid_subsequence(subseq) and has_nesting(subseq):
            return True

    return False

