from typing import List

def fix_spaces(text: str) -> str:
    """
    Given a string text, replace all spaces in it with underscores, 
    and if a string has more than 2 consecutive spaces, 
    then replace all consecutive spaces with a single hyphen (-).

    :param text: Input string to process
    :return: Processed string with spaces replaced according to rules
    """
    result: List[str] = []  # List to store the result characters
    space_count: int = 0  # Counter for consecutive spaces
    in_spaces: bool = False  # Flag to track if currently in a space sequence

    for char in text:
        if char == ' ':
            space_count += 1
            in_spaces = True
        else:
            # Handle the end of a space sequence
            if in_spaces:
                if space_count > 2:
                    result.append('-')
                elif space_count == 1:
                    result.append('_')
                # For 2 spaces, append two underscores (as per the requirement to replace individual spaces with underscores)
                else:
                    result.extend(['_', '_'])
                in_spaces = False
                space_count = 0
            result.append(char)  # Append non-space character

    # Handle the end of the string in case it ends with spaces
    if in_spaces:
        if space_count > 2:
            result.append('-')
        elif space_count == 1:
            result.append('_')
        # For 2 spaces, append two underscores
        else:
            result.extend(['_', '_'])

    return ''.join(result)

