from typing import List

def specialFilter(nums: List[int]) -> int:
    """Write a function that takes an array of numbers as input and returns 
    the number of elements in the array that are greater than 10 and both 
    first and last digits of a number are odd (1, 3, 5, 7, 9).

    :param nums: List of integers
    :return: Number of elements meeting the criteria
    """
    def is_odd_digit(digit: int) -> bool:
        """Check if a digit is odd."""
        return digit in {1, 3, 5, 7, 9}

    def get_first_last_digits(num: int) -> tuple:
        """Extract first and last digits of a number, handling negatives."""
        num = abs(num)  # Handle negative numbers
        last_digit = num % 10
        while num >= 10:
            num //= 10
        first_digit = num
        return first_digit, last_digit

    count = 0
    for num in nums:
        if num > 10:
            first_digit, last_digit = get_first_last_digits(num)
            if is_odd_digit(first_digit) and is_odd_digit(last_digit):
                count += 1

    return count

